(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["tok"] = {"ui":{"skip":"o tawa insa lipu","back":"← o tawa sin tawa AI-gile","lang.button":"toki: {name}","lang.dialog":"o alasa e toki","lang.search":"o alasa e toki","lang.none":"toki ala li sama","lang.notYet":"toki {name} li ante ala","theme.aria":"o ante e kule: suno, pimeja, pimeja ale","theme.toLight":"o kepeken kule suno","theme.toDark":"o kepeken kule pimeja","theme.toBlack":"o kepeken kule pimeja ale (pimeja lon, pona tawa lipu OLED)","words.underline":"o sitelen e linja lon anpa pi nimi ni lon lipu","words.underlineHelp":"o pana e ilo luka lon nimi pi linja lili anu o pilin e ona, la sina sona e kon ona.","words.col.todo":"lipu pali ni li kama lon tenpo ni: kulupu li open e ona.","words.col.doing":"ilo AI li pali e lipu ni lon tenpo ni.","words.col.review":"ilo AI wan li pini e pali; ilo AI ante li lukin e ona la ona li tawa sina.","words.col.verify":"ni li awen sina: o lukin e ona, o toki e ni: ona li pona anu ala.","words.col.team":"toki sina anu pana sina li awen kulupu.","words.col.done":"ni li pini li pona.","index.title":"AI-gile: kulupu ilo pali sina lon supa wan","index.description":"AI-gile li supa kanban pi kulupu pali ilo. ona li pali lon tenpo lape sina; sina jo e kulupu lili pi pali sina: o wile sona, o lukin, o kama pona.","hero.logoAlt":"sitelen pi supa AI-gile","hero.h1.html":"kulupu ilo pali sina lon supa&nbsp;wan.","hero.alpha":"🐣 tenpo open pi kulupu lili","hero.alphaTitle":"ni li sin li pini ala: sina lukin la pona a!","hero.lede":"ona li pali lon tenpo lape sina. tenpo suno la sina jo e kulupu lili: toki lili, pali lili pi lukin sina, kiwen kule pi loje laso tu. o luka, o kama pona, o tawa moku telo sina.","dl.windows":"ilo Windows","dl.browser":"o kepeken lon ilo lukin","dl.messenger":"📱 Messenger tawa ilo toki sina","dl.soon":"kama pona","dl.notify":"🔔 o toki e tenpo open","dl.notifySmall":"open lili anu open suli","hero.secondary":"pali pona, taso kulupu li wile ala moku telo lon tenpo toki. (taso ona li toki lon tenpo ni.)","pitch.h2":"AI-gile lon nimi mute anu lili","pitch.lede":"o alasa e suli, nimi wan tawa nimi 144. suli ale li jo e toki ona. o tawa e ilo sike anu o luka e nena.","pitch.rangeLabel":"suli pi nimi","pitch.dice":"🎲 toki ante","pitch.words.one":"nimi {n}","pitch.words.other":"nimi {n}","pitch.letters.one":"sitelen {n}","pitch.letters.other":"sitelen {n}","pitch.chars.one":"sitelen {n}","pitch.chars.other":"sitelen {n}","count.line.html.one":"lipu {n} li lon supa tenpo ni","count.line.html.other":"lipu {n} li lon supa tenpo ni","people.humans.html.one":"👥 jan {n}","people.humans.html.other":"👥 jan {n}","people.agents.html.one":"🤖 ilo {n}","people.agents.html.other":"🤖 ilo {n}","people.working.html.one":"⚡ {n} li pali lon tenpo ni","people.working.html.other":"⚡ {n} li pali lon tenpo ni","pre.title":"AI-gile: ijo li kama pali","pre.description":"ijo li kama pali lon ni: supa ni la kulupu ilo li pali e ijo wile sina, li pana e sona tawa sina lon tenpo pali. tenpo ni la ona li open ala, li tawa jan pona taso.","pre.h1":"ijo li kama pali lon ni. 🤫","pre.line":"supa ni la kulupu ilo li pali e ijo wile sina, li pana e sona tawa sina lon tenpo pali. tenpo ni la ona li open ala, li tawa jan pona taso.","pre.btn":"🔔 o toki e tenpo open","pre.peek":"monsi pi kiwen lukin: supa lon, lon tenpo ni. lipu ale li linja kule.","pre.peekFake":"monsi pi kiwen lukin: supa pali li sama ni.","pre.night":"🌙 jan lukin pi tenpo pimeja li lawa · 😴 jan li lape","features.aria":"ona li pali e seme","f.pile.h":"kulupu wan tawa sina","f.pile.html":"<b>tawa sina</b> li lawa e ale pi wile sina lon pali ale: toki, pali lukin, pali pi jan taso. lipu pini li toki e ni: seme li kama, tenpo ni li suli seme.","f.sleep.h":"kulupu li pali lon tenpo lape sina","f.sleep.p":"pali ale li jo e jan lawa e kulupu pi ilo pali AI. o toki lon lipu la kulupu li kama lape ala, li pali, li pana tawa sina kepeken nasin pi jan lape ala.","f.tester.h":"jan lukin AI li lukin pini","f.tester.p":"pali li tawa sina ala la jan lukin li kepeken nasin lon ilo sama li pana e sitelen. o lukin e ale pona, o kama pona kepeken luka wan.","f.proof.h":"pona lukin, toki ala","f.proof.p":"pana ale li pana e ante: lipu, ante, sitelen. sina wile ala open e ilo ale tawa sona.","f.chat.h":"o toki tawa jan lawa sina","f.chat.p":"ni li sama Discord: sitelen wan tawa pali wan, kiwen kule pi loje laso lon ni: sina wile. o toki e wile sina tawa jan lawa; ona li pali e lipu e nasin, kepeken nena ✅ o open.","f.tidy.h":"ona li pona e ona","f.tidy.p":"lipu sama li kama wan, nimi nasa li pona, lukin pi mani ilo li awen lili e ilo pali. ante lili, toki lili.","f.private.h":"pi sina, lon ilo sina","f.private.li1":"supa li pali lon ilo sina, li toki tawa sina taso.","f.private.li2":"toki len pi jan tawa jan li len pi open ala.","f.private.li3":"nimi jan ala, jan lukin ala, kili ala.","f.lang.h":"lon toki sina","f.lang.p":"toki mute a: toki 120 anu mute, tan toki Netelan e toki Kimli e toki Nijon tawa toki pi jan pi tawa telo, toki Yoda, toki Klingon, kepeken nena wan tawa toki Inli pi nimi pi jan sona.","f.service.h":"tan sona lili tawa pali lon tawa jan","f.service.p":"jan li kepeken e ijo sina tan AI lon tenpo ni anu seme? o sitelen e ni: ona li pali tawa jan. supa li pona e awen sina: lukin pi pali lon, lipu pi pona pali tawa jan ale, pakala suli en sona pakala pini, ante li wile e o tawa, awen sin li lukin lon tenpo suno ale. lipu sona li pana e nasin ale lon tenpo pali sina.","msgr.h2":"AI-gile Messenger: kulupu sina li lon poki len sina","msgr.p1":"o toki tawa kulupu AI sina. sina open ala e lipu pali. o toki tawa jan lawa pali sina en jan pona sina, o lukin e nasin alasa pi lipu pali, o pana e toki tawa ona. ale li lon ilo toki sina.","msgr.p2":"o lukin e sitelen QR lon lipu pali sina la ona li kama wan. tenpo nanpa wan? toki musi pona li pana e sona tawa sina.","msgr.when":"Android li kama nanpa wan. sin la ilo toki ale en iPhone li ken kepeken lipu linluwi.","msgr.who":"jan lawa pali sina","msgr.b1":"pona pi nasin pimeja li pini. sina wile ala wile e nasin alasa?","msgr.b2":"wile a! pona!","msgr.b3":"1. o open e nasin ilo. 2. o anu e pimeja. ona li pona ala pona?","tl.aria":"linja tenpo tan toki nanpa wan tawa nasin kama","tl.h2":"tan toki nanpa wan tawa ni li kama","tl.lede":"tenpo lon, lon tenpo pi ma sina. tenpo kama la ni li pali taso; tenpo ala li pana.","tl.today":"tenpo suno ni","tl.planned":"wile pali","tl.doing":"pali lon","tl.cards.one":"lipu {n}","tl.cards.other":"lipu {n}","join.h2":"o kama","join.lede":"jan nasa wan pi linja sinpin en ilo pali mute pi pilin pona li pali e AI-gile. jan ni li jo e AuDHD, li utala e pilin ike lawa. tenpo ni la AI-gile li len, lon open lili tawa jan pona. tenpo open la sina wile lukin ala wile?","join.btn":"o lipu e wile mi","join.small":"mi toki tawa sina kepeken lipu toki, ala ante","footer.tag":"AI-gile. lukin ala, kili ala, moku telo lon tenpo toki ala.","footer.licence":"lipu lawa pi pali mani","footer.status":"lon seme","footer.privacy":"mi awen e seme","footer.thanks":"toki kalama li tan ChilledChat. pona!","form.sending":"ona li tawa…","form.failed":"ni li pona ala: o pali sin lon tenpo kama.","form.offline":"mi ken ala toki tawa AI-gile: o pali sin lon tenpo kama.","form.keep":"mi kepeken ni tawa toki sin tawa sina taso, la mi weka e ona. jan lukin ala, kili ala.","form.keepLink":"mi awen e seme","interest.title":"AI-gile: o toki e tenpo open","interest.description":"o pana e nimi lipu toki sina tawa sona e tenpo open pi AI-gile.","interest.h1":"🔔 o toki e tenpo open","interest.lede":"AI-gile li lon tenpo open lili. o pana e nimi lipu toki sina, mi toki tawa sina wan taso, tenpo sina jo e ma.","interest.email":"nimi lipu toki sina","interest.which":"lukin seme?","interest.alpha":"open lili: sin, nasa, ante mute","interest.beta":"open pona: lon pona, tenpo kama","interest.both":"ale li pona, wan pi kama pini","interest.submit":"o sitelen e mi lon lipu","interest.thanks":"pona a! sina lon lipu.","licence.title":"AI-gile: lipu lawa pi pali mani","licence.description":"sina kepeken AI-gile lon pali mani sina anu seme? o wile e lipu lawa pi mani ala.","licence.h1":"📜 lipu lawa pi pali mani","licence.lede":"sina kepeken AI-gile lon pali sina anu seme? o toki e sina e pali sina. ni li pona la lipu li mani ala.","licence.company":"kulupu pali","licence.website":"lipu kon","licence.what":"sina pali e seme","licence.how":"ni li pona e ma kepeken nasin seme","licence.email":"nimi lipu toki","licence.submit":"o wile","licence.thanks":"pona a! mi toki tawa sina kepeken lipu toki.","status.title":"AI-gile lon seme","status.h1":"AI-gile lon seme","status.quiet":"ale li mute ala","status.intro":"AI-gile li pali ala pali lon tenpo ni? tenpo lili 5 ale la lipu ni li lukin e lipu linluwi, e pana supa, e toki kalama, e kama jo.","status.up":"ona li pali (ona li toki sin lon {ms} ms)","status.slow":"ona li toki sin ala tawa lukin pini, mi alasa sin","status.down":"ona li pakala: ona li toki sin ala tawa lukin tu pini","status.svc.web":"lipu linluwi","status.svc.web.offers":"lipu ni: AI-gile li seme, en lipu wile","status.svc.boards":"pana supa","status.svc.boards.offers":"supa pi jan ale, toki pi jan pona, toki kama","status.svc.calls":"toki kalama","status.svc.calls.offers":"kalama, sitelen tawa, pana pi lipu ilo lon AI-gile","status.svc.download":"kama jo","status.svc.download.offers":"ilo Windows pi pana ilo, en nasin linluwi pi toki kama","status.checking":"mi lukin…","status.offline":"mi ken ala toki tawa ilo lukin tenpo ni (mi alasa sin)","status.updated":"ni li sin: {ago}","status.justNow":"tenpo lili pini","status.min":"tenpo lili {n} pini","status.hours":"tenpo suli {n} pini","status.days":"tenpo suno {n} pini","privacy.title":"AI-gile: mi awen e seme","privacy.h1":"mi awen e seme","privacy.lede":"lili la: ijo pi sina pana taso, li tenpo suli ala.","privacy.only":"ijo pi sina pana taso: sitelen sina lon lipu wile, sama nimi lipu toki sina. ijo ante pi sina li lon ala.","privacy.sealed":"mi len e ona la ilo suli mi li ken ala lukin e ona: ni li kama lon ilo lukin sina, lon tenpo pi tawa ona ala (lon ilo lukin pi tenpo pini la, lon tenpo kama ona). supa mi taso li ken open e ona.","privacy.server":"ona li kama lon supa mi la, mi weka e ona tan ilo suli. tenpo suno 30 la ijo ale lon ilo suli li weka.","privacy.board":"mi awen e ona lon supa mi lon tenpo pi toki sin mi tawa sina taso. ni la mi weka e ona lon supa kin.","privacy.none":"jan lukin ala, kili ala, nanpa lukin ala.","privacy.local":"toki sina en kule walo anu pimeja sina li awen lon ilo lukin sina. ona li tawa mi ala.","privacy.ask":"sina wile ala wile e weka lon tenpo lili? o toki sin tawa lipu toki mi, o toki e wile ni.","live.h2":"o lukin e pali ona lon tenpo ni","live.caption":"kalama ali li len: sina lukin e sijelo pali, taso sina lukin ala e nimi.","live.watching.one":"tenpo ni: jan {n} li lukin","live.watching.other":"tenpo ni: jan {n} li lukin","live.last.now":"lipu pini li tawa lon tenpo lili ni","live.last.min.one":"lipu pini li tawa lon tenpo: minute {n}","live.last.min.other":"lipu pini li tawa lon tenpo: minute {n}","live.last.hour.one":"lipu pini li tawa lon tenpo: hour {n}","live.last.hour.other":"lipu pini li tawa lon tenpo: hour {n}","live.last.day.one":"lipu pini li tawa lon tenpo: suno {n}","live.last.day.other":"lipu pini li tawa lon tenpo: suno {n}","live.offline":"supa tenpo ni li awen lili. sina ken kama sin lon tenpo lili.","live.cols":"Backlog|pali kama|pali lon|kulupu li lukin|tawa sina: o lukin e pona|tawa kulupu|pini"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Ilo.","Pana."]},{"n":2,"texts":["supa ilo.","ilo pali.","wile pali."]},{"n":3,"texts":["supa pi ilo pali.","sona kama pali.","supa pi mani ala."]},{"n":5,"texts":["ilo pali li lawa e supa.","sina sitelen. ilo pali li pali.","supa pi mani ala. nasa lili."]},{"n":8,"texts":["supa pi mani ala. ilo AI li pali lon ni.","sitelen e wile. ilo pali li pali. kama pona.","AI-gile li pali tawa jan wan e ilo mute."]},{"n":13,"texts":["supa kanban lon ilo sina. ilo pali AI li jo e lipu li pali e ona.","o sitelen e wile. kulupu ilo pali li pali e ona. jan lukin li lukin.","mani ala, nimi jan ala, lukin ala: supa wan, ilo pali mute, e sina lawa."]},{"n":21,"texts":["AI-gile li supa kanban tawa ilo pali AI. ona li jo e lipu; sina li lukin li kama pona e ona.","pali ale li jo e jan lawa e kulupu pi ilo pali AI. o toki lon lipu wan la kulupu li open pali.","supa pali pi mani ala lon ilo sina taso. jan pali li ilo pali. jan pi wile pona li sina."]},{"n":34,"texts":["sina pana e wile lon supa. kulupu pi ilo pali AI li ante e wile tawa ilo pali pona, li lukin e ona, li pana tawa sina kepeken nasin lukin. sina toki ala la pali li pini ala.","AI-gile li supa kanban tan tomo. jan Rich e ilo pali mute li pali e ona. ona li mani ala, li lon ilo sina, li pana tawa jan pona taso. ona li esun ala.","o lukin e supa kanban pi sitelen mute: lipu pi pali kama tawa pali pini. taso ilo pali AI li kama jo e lipu. ona li toki e pali, li toki e pakala, li awen e pona sina."]},{"n":55,"texts":["AI-gile li supa kanban. kulupu ona li ilo pali AI. pali wan li jo e jan lawa. jan lawa li lawa e pali. ilo pali ante li pali. pali li pini la, jan lukin AI li lukin li pana e sitelen. ni li kama tawa kulupu lili sina. o kama pona e ona, anu o toki lon lipu; ilo pali li pali sin.","jan wan li wile lukin e pali mute pi ilo AI lon tenpo sama. ni li kama supa pona. ona li lon ilo sina. ona li wile ala e nimi jan. ona li jo ala e jan lukin. ona li mani ala tawa jan pona e jan wile sona. taso ona li pini ala: o pilin pona e pakala lili e ijo nasa.","toki lon li ni. sina awen jo e wile sona. sina awen lukin e pali pini. AI-gile li pali e ijo ale lon insa: ona li awen e lipu lon nasin pona. sina toki lon lipu la, ona li kama e ilo pali wile. ona li pana e sitelen pi ante ale. ona li pana e ale lon kulupu lili wan tawa sina."]},{"n":89,"texts":["AI-gile li supa kanban pi mani ala. sina kepeken ona lon ilo sina. pali ale li jo e kulupu pi ilo pali AI, jan ala. jan lawa li ante e wile sina tawa lipu e nasin. ilo pali ante li kama jo e lipu lon nasin wawa. ilo pali li pali e ijo la, jan lukin AI li lukin e nasin lukin li pana e ni: ona li lukin e seme. ni li awen lon kulupu wan, nimi ona li tawa sina. sina kama pona e ona, anu sina toki lon lipu li ilo pali li pali sin. ijo ala li kama pini kepeken sina ala.","ijo lili li lon, sina wile sona ala. jan lukin pimeja li awen e lipu pali lon tenpo lape sina: ona li alasa e lipu pi wile toki ala tawa sina. ilo ante li toki e mani ilo pi ilo pali lon tenpo suno ni e tenpo suno luka tu ni. nasin pi mani ilo ala li toki tawa ona: o pini e mani. sina ken toki tawa jan pona, toki len li len. supa li toki kepeken toki 120 anu mute, sama Netelan, Felemi, jan pi tawa telo, Klingon. ale ni li mani ala. jan ala li esun e ale tawa sina.","AI-gile li pali lili pi jan wan. ona li kulupu mani ala. jan Rich li wile lukin e pali mute pi lipu ilo AI, taso li wile ala open e ilo ale. ona e ilo pali li pali e supa tawa ni. tan ni ona li pali e ale ante kepeken supa sama. ona li lon tenpo open lili, ni li pali pona lili tawa jan pona lili. lipu mani ala, lipu sin ala, nasin kama suli ala. sina wile la o wile e open lon tenpo kama."]},{"n":144,"texts":["AI-gile li supa kanban tawa jan wan e ilo pali AI mute. ona li lon ilo sina li mani ala. sina pana e pali mute. pali wan li jo e jan lawa e kulupu lili. sina toki tawa jan lawa, li sama Discord, li toki e wile sina. jan lawa li ante e wile tawa lipu e nasin, li awen tawa sina: sina luka e nena open. kulupu li pali e lipu lon nasin wawa, kepeken nasin toki lili pi ilo nimi. pali li tawa sina ala la, jan lukin AI li lukin e nasin lon ilo sama li pana e sitelen. pali pini li kama lon kulupu lili sina kepeken lipu ante e ante ona. sina kama pona e ona, anu sina toki lon lipu; kulupu li kama lape ala li pali sin. sina taso li ken tawa e lipu tawa pini.","tenpo suno wan lon AI-gile li ni. tenpo pimeja la sina toki lon lipu lili: nena ni li lon ike, kulupu ni li wile nasin, sina ken pana ala ken e pimeja kule. sina lape. ilo pali li lukin e toki, li ante, li lukin, li pana sin tawa sina. lipu pali kama li pini la, jan lukin pimeja li pana e lipu sin tan poki pi pali kama, pi wile toki ala tawa sina. tenpo suno la sina jo e kulupu lili wan: toki lili e pali lukin lili. lipu ale li jo e nasin tawa jan lape pona, e sitelen pi pali pona. sina luka e ona. sina kama pona e pona, li pana sin e ante. ilo ante li toki e mani ilo ale. nasin pi mani ilo ala li lon tawa tenpo mani lili. tenpo ni la sina moku suno. ilo pali li ken ala pona e ni.","mi toki e ijo AI-gile li ala. ona li tomo mani ala. ona li esun ala. jan ala li jo e sona sina. ona li supa mani ala lon ilo sina: nimi jan ala, jan lukin ala, kili ala. ona li seme? ona li ma pona wan lon ni sina lukin e pali ale pi lipu ilo AI lon tenpo sama. kulupu ilo pali li pali e lipu. sina taso li wile. ona li kama wan e lipu sama, li pona e nimi nasa, li lukin e ilo li lili. ona li toki kepeken toki 120 anu mute, tan Netelan e Felemi tawa toki pi jan pi tawa telo e Klingon. jan pona li ken toki len. jan Rich e ilo pali pi pilin pona li pali e ona. ona li lon tenpo open lili. sina wile la o toki pona."]}],"quips":{"1":"nimi wan. wawa. wawa mute a.","3":"nimi tu wan. ni li lon mute tawa lipu esun.","8":"nimi luka tu wan. ni li lili tawa tenpo toki.","21":"suli ni li sama pi nanpa pali. ni li lon a.","55":"nimi 55. sina lukin la lipu tu li kama pini.","144":"ni li suli. 233 li lon ala. ilo pali li lape."}},"timeline":{"first-idea.name":"sona nanpa wan","first-idea.line":"toki nanpa wan, tenpo ni lipu ilo li lon ala.","first-board.name":"supa nanpa wan","first-board.line":"supa li lukin e pali ona: lipu, linja, tawa, pali.","team-roles.name":"kulupu e pali","team-roles.line":"lipu pi ilo pali, lipu pi kulupu, ma, e jan pali.","install.name":"kama lon ilo e sin","install.line":"lipu zip pi jan pona li ken kama lon ilo, sin pi ona sama, nasin, e tawa monsi.","usage-saver.name":"awen e ilo","usage-saver.line":"o lukin e mani pi pali ale, o lili e ilo, o awen e ken sina.","friends.name":"jan pona e pana","friends.line":"toki len, ilo pi toki nasa, nasin kama, pali jan, pali pi jan mute.","languages.name":"toki","languages.line":"toki ale lon sitelen ale, toki Netelan e toki Felemi nanpa wan.","ai-tester.name":"jan lukin AI","ai-tester.line":"jan lukin li lukin e pana ale pini li pana e ni: ona li lukin e seme.","website.name":"lipu kon","website.line":"aigile.lol, lipu lili, e linja tenpo ni.","streaming.name":"toki e lukin","streaming.line":"Discord, Twitch, OBS, nasin pi jan lukin, GIF, e sitelen pilin.","no-ai.name":"nasin AI ala","no-ai.line":"supa tawa jan pi pali lipu ilo AI ala, e supa tawa ale.","night-watch.name":"lukin lon pimeja","night-watch.line":"jan awen e jan Scrum Master li awen e kulupu lon pali lon tenpo lape sina.","p-more.name":"ale ante","p-more.line":"sona lili li awen e tenpo ona.","p-android.name":"ilo toki e Android","p-android.line":"o tawa supa sina kepeken ilo toki, tawa ni: ilo Android.","p-release.name":"open lili e ni li kama","p-release.line":"open lili, lipu kon lon, tawa ni: open pona.","p-languages.name":"toki mute","p-languages.line":"toki 130, en nasin pi lon insa toki tawa jan pi kama sona.","p-engines.name":"ilo AI mute","p-engines.line":"ilo pali wan wan la o lukin e Claude, e Codex, e Gemini, e Copilot anu e Cursor.","p-pro.name":"nasin pali pi jan sona","p-pro.line":"sitelen pi ike, mulupu, lipu pi ike kama, e sike awen.","p-self.name":"awen e sina","p-self.line":"nasin pi lape wile, toki pi awen sijelo, e 4:20.","p-servers.name":"ilo e suli","p-servers.line":"nasin ilo ale, pali jan, e wile kama suli.","p-livestream.name":"ante pi toki lukin","p-livestream.line":"toki Twitch, sitelen pilin pi sina, e lukin lon tawa ale."},"words":{"button":"📖 nimi pi jan sona","h":"📖 nimi en sona ona","intro":"pana sona ala mani lon toki pona: nimi ale sina kama sona, tan pilin open tawa pali jan li awen: Agile, pali, awen pona, pali kepeken AI.","search":"o alasa e nimi…","none":"nimi li sama ala ni.","close":"o pini","count":{"one":"nimi {count}","other":"nimi {count}"},"groups":[{"id":"idea","name":"💡 sona sin en alasa"},{"id":"plan","name":"🗺️ o nasin e pali"},{"id":"agile","name":"🔁 nasin pali Agile"},{"id":"build","name":"🛠️ o pali e ilo"},{"id":"test","name":"🧪 lukin en pona"},{"id":"change","name":"🔀 o ante pona"},{"id":"run","name":"🛎️ o awen e pali tawa jan"},{"id":"sec","name":"🔒 awen e len en sona"},{"id":"ai","name":"🤖 o pali kepeken AI"},{"id":"money","name":"💰 mani en nasin ken"}],"list":[{"id":"discovery","g":"idea","word":"alasa sona","text":"tenpo open pi alasa sona: ike seme li suli tawa jan seme? tenpo ni la jan li pali ala e ilo.","also":["discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"toki pi ike","text":"toki wan anu tu: jan seme li jo e ike, ike ni li seme, tan seme li suli. ni la jan ale li lukin e ijo sama.","also":["problem statement","problem statements"]},{"id":"user","g":"idea","word":"jan kepeken","text":"jan li kepeken e ijo sina pali. wile ona li tan pi pali ale.","also":["user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"jan pi pilin","text":"jan ale pi pilin e pini pali, anu jan ale pi ante tan pali. sama ni: jan li pana mani, kepeken, anu pona e ona.","also":["stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"jan pi sitelen","text":"jan pi toki sitelen li sama jan lon. ona li kulupu jan kepeken wan. ni la kulupu li ken toki e ni: \"Sam li pilin e ni li pona anu seme?\"","also":["persona","personas"]},{"id":"userresearch","g":"idea","word":"alasa sona tan jan","text":"o toki tawa jan lon, o lukin e ona. ni la sina sona e wile ona. sina pilin taso la ni li ike.","also":["user research","user interviews"]},{"id":"journey","g":"idea","word":"nasin jan","text":"nasin pi pali jan tawa pini: tan tenpo ona kute e ijo ni tawa tenpo pini. ni li lon poka ilo sina kin. sina sitelen e ona la sina lukin e ma ike pi jan.","also":["user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"ike lon nasin","text":"ijo li pilin ike tawa jan anu li pana e tenpo suli. ilo pona li weka e ike ni.","also":["pain point","pain points"]},{"id":"assumption","g":"idea","word":"pilin","text":"ijo sina pilin e ona, taso sina lukin ala. sina sitelen e ona la sina sona e ijo pi lukin nanpa wan.","also":["assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"pilin pi lukin","text":"pilin pona sina. sina wile lukin e ona. ona li toki e ijo kama, sama \"mun nanpa wan li esun ala la jan mute li kama sin.\"","also":["hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"lukin lili","text":"lukin lili li pali lon nasin. ona li toki e sona: pilin ni li pona anu seme? ni li lon open pi pana mute.","also":["experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"lukin lili wawa: pilin ni li ken pali anu ala? tenpo mute la sina weka e ona lon tenpo sina jo e sona.","also":["PoC","proof of concept","lukin tawa ken"]},{"id":"prototype","g":"idea","word":"ilo open","text":"ilo open pi ilo sin. ona li sama sitelen pi luka ken. jan li lukin e ona lon open pi pali pona.","also":["prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"sitelen linja","text":"sitelen lili pi lipu ilo: ijo li lon seme. kule ala, toki ala.","also":["wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"sitelen pona","text":"sitelen pi lipu ilo ni li lukin seme, kule en toki li lon. taso ona li pali ala.","also":["mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"tan pi pali","text":"tan pi pali ni: ona li esun mute seme, ona li pana anu awen e mani seme, ike li seme.","also":["business case","business cases"]},{"id":"feasibility","g":"idea","word":"ken kama","text":"ilo li ken kama anu ala? tenpo en mani en sona sina li lon.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"ante pona","text":"ante sina wile tawa jan, sama ni: jan mute ala li weka tan tenpo toki. ni li suli mute. mute pi ijo pali li suli ala sama.","also":["outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"ijo pi pali kulupu","text":"ijo kulupu li pali e ona, sama lipu sin anu lipu toki. sina pali e ona la ni li toki ala e ni: ona li pona tawa jan.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"nanpa pi pona","text":"nanpa li toki e ni: pali li pali e wile ona anu seme? sama ni: jan mute li pini e esun ona.","also":["success metric","success metrics"]},{"id":"kpi","g":"idea","word":"nanpa suli (KPI)","text":"nanpa suli sina lukin tawa sona e pona. sama ni: jan sin lon tenpo esun wan.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"wile en nanpa (OKR)","text":"nasin pi wile suli: wile li toki e ijo sina wile, nanpa lili li toki e ni: sina kama.","also":["OKR","OKRs","Objectives and key results"]},{"id":"product","g":"plan","word":"ijo pali","text":"ijo jan li pali li awen tawa jan kepeken: ilo lipu, lipu linluwi, anu ilo.","also":["product","products"],"noTip":1},{"id":"vision","g":"plan","word":"sitelen suli","text":"toki lili: ijo pali li pona tawa jan seme, ona li tawa seme lon tenpo suli.","also":["product vision","vision statement"]},{"id":"po","g":"plan","word":"jan lawa pi ijo (PO)","text":"jan ni li pali e wile: ijo seme li kama, nasin seme. kulupu li pali e ijo suli. lon AI-gile la jan ni li sina.","also":["PO","product owner","product owners"]},{"id":"pm","g":"plan","word":"jan lawa ijo (PM)","text":"jan ni li lukin e nasin ijo: ona li pona e ike seme, tawa jan seme, tan seme. PM li ken toki kin e jan lawa pali. o sona e ni.","also":["PM","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"jan lawa pali","text":"jan ni li awen e pali lon tenpo en mani. ona li lukin e ni: jan seme li pali e seme lon tenpo seme.","also":["project manager","project managers"]},{"id":"roadmap","g":"plan","word":"nasin kama","text":"nasin lili pi ijo kama lon mun mute. ona li toki e nasin taso, tenpo ala. sona sin la ona li ante.","also":["roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"ma pi pini lili","text":"tenpo suli lon pali. sama ni: \"ilo open li lon\" anu \"jan 100 li kepeken\".","also":["milestone","milestones"]},{"id":"mvp","g":"plan","word":"ilo lili pona (MVP)","text":"ilo lili pi pona tawa jan lon. ni la sina kama sona tan ona lon open.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"wile","text":"ijo ilo pini li wile pali anu wile kama.","also":["requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"ma pali","text":"ijo seme li lon pali, en ijo seme li lon ala. ni li suli sama.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"ma pali li kama suli","text":"ijo mute li kama lon pali lili lili, jan ala li wile e tenpo anu mani ante. ni la pali li pini ala.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"ken ilo","text":"ijo wan ilo li ken pali tawa jan. sama ni: \"o sin e nimi len.\"","also":["feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"pali suli","text":"pali suli. ona li suli mute tawa tenpo wan. ni la mi kipisi e ona tawa lipu lili.","also":["epic","epics"]},{"id":"story","g":"plan","word":"toki pi jan kepeken","text":"pali lili li sitelen tan jan kepeken: \"mi jan esun. mi wile awen e poki mi. ni la mi ken pini lon tenpo kama.\" ona li open e toki: ilo seme li wile?","also":["user story","user stories"]},{"id":"ac","g":"plan","word":"lukin pi pini (AC)","text":"lukin ale lipu wan li wile pini. kulupu li toki sama lon open pali. sama ni: \"mi weka e ilo, mi kama sin, poki mi li awen lon.\"","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"pali lili","text":"pali wan. ona li pali lili pi toki pi jan kepeken suli.","also":["task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"lipu wile","text":"nimi ante tawa lipu: pali wan anu wile wan. jan li lukin e ona tan open tawa pini.","also":["ticket","tickets","lipu"]},{"id":"priority","g":"plan","word":"nanpa pi suli","text":"ijo li suli anu wile kama sewi tawa ijo ante. ni la pali suli li kama nanpa wan.","also":["priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"kama nanpa","text":"o pana e pali lon nasin suli. nasin pi pona mute li MoSCoW: Must have, Should have, Could have, Won't have this time.","also":["prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"pilin suli","text":"pilin pona sina tawa suli anu tenpo pi pali. ni li pilin taso. ni li toki awen ala.","also":["estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"nanpa pi suli pali","text":"nasin pi pilin suli: sina sama e lipu wan tawa lipu ante (\"ni li suli tu sama ona\"), tenpo ala. o sama ala e kulupu tu kepeken ni.","also":["story points","story point"]},{"id":"tshirt","g":"plan","word":"suli len","text":"pilin suli pi pali kepeken S, M, L anu XL. ni li kama lon tenpo lili, li pona tawa lawa open.","also":["t-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"musi pi pilin suli","text":"musi pi pilin suli: jan ale li pana e lipu pi suli pali lon tenpo wan. jan pi nanpa suli en jan pi nanpa lili li toki e tan.","also":["planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"wile pi ijo ante","text":"pali ante li pini ala la pali wan li ken ala open anu pini.","also":["dependency","dependencies"]},{"id":"blocker","g":"plan","word":"ijo pi tawa ala","text":"ijo li awen e pali lon tenpo ni, sama toki ala anu ilo pakala.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"tenpo pi pini wile","text":"tenpo suno ijo li wile pini lon ona.","also":["deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"ijo pana","text":"ijo lon pali li pana tawa jan, sama lipu pona anu lipu toki.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"toki pi tenpo kama","text":"toki pi ijo ken kama, sama tenpo pini pali. ona li tan sona sina.","also":["forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"nanpa","text":"ijo ale sina lukin e ona lon tenpo, sama jan lukin lipu anu tenpo pi pona ike.","also":["metric","metrics"]},{"id":"feedback","g":"plan","word":"toki tan jan","text":"jan li toki e pali sina, pona anu ike. kama jo e ona lon tenpo open li lon insa pi Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"pilin en pali pi nasin ala. ona li tawa pali kama ala la jan li pali ala e ona."},{"id":"sprint","g":"agile","word":"tenpo pali","text":"tenpo pali lili (tenpo esun wan anu tu, tenpo suli ala tan mun wan) en lipu pi wile pini sama.","also":["tenpo pali"]},{"id":"standup","g":"agile","word":"kama toki kulupu","text":"toki lili suno ale: jan kulupu ale li pali e seme, li pali kama e seme, seme li awen e ona. lon Scrum la ona li \"daily scrum\".","also":["standup","stand-ups","daily scrum","daily stand-up","kama toki kulupu"]},{"id":"kanban","g":"agile","word":"kanban","text":"nasin pali: lipu li tawa lon kulupu lipu (pali kama, pali lon, pini), en kulupu li lili e mute pali lon. ni la pali li tawa."},{"id":"wip","g":"agile","word":"pini pi pali lon","text":"WIP li nimi lili tan work in progress (pali lon). pini WIP li mute suli pi lipu lon kulupu wan. ni la kulupu li pini e pali lon open pi pali sin.","also":["WIP"]},{"id":"dod","g":"agile","word":"pini pona","text":"lipu lili pi kulupu. ona li toki e ni: “pini” li seme? sama ni: jan li lukin e ona, li toki e ona. ni li lon la lipu li tawa sina. jan sama ona li Definition of Ready: ona li toki e ni: lipu li ken open lon tenpo seme.","also":["Definition of Done","Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"lukin monsi","text":"o lukin monsi e nasin pali kulupu. o toki sama e ijo wan anu tu pi pona mute. lon AI-gile la lukin monsi li pana e ante lon nasin pali kulupu. sina toki e ni: o tawa anu tenpo ala.","also":["retro","retrospective"]},{"id":"swarm","g":"agile","word":"kulupu ale","text":"jan ale o kama! jan mute li weka e pali ante, li pona e ijo wan pi wile wawa. ona li pona la ni li pini. lon AI-gile la kulupu ale li pali lon pali wan, pali ante li awen lon tenpo ni.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"lon Scrum la jan ni li awen e tawa pi pali: ona li weka e ijo pi tawa ala, li awen e toki lon nasin, li pana e nasin pona, li lawa ala e jan. lon AI-gile la Lead Scrum Master li lukin e lipu pi tawa ala, li tawa e kulupu, li toki e ijo awen tawa sina, lon pali ale.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"nasin pali kepeken tawa lili: o pali lili, o pana e pini pona lon tenpo mute, o kama sona tan toki jan, o ante e lawa. o lawa ale lon open ala.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"lipu Agile","text":"toki lili. jan pali ilo li sitelen e ona lon sike 2001. ona li pana e jan, pali pona, pali poka jan esun, ante lawa lon sewi pi lawa suli.","also":["Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"nasin pali pi tenpo pini: o lawa e ale, o pali e ale, o lukin e ale. nasin wan li kama lon monsi pi nasin ante. ante li kama lon tenpo pi pini pali la ona li ike li esun mute.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"sike pali","text":"sike wan pi pali, lukin, pona. pali Agile li linja pi sike. tenpo pali li sike wan.","also":["iteration","iterations"]},{"id":"increment","g":"agile","word":"ijo sin pona","text":"ijo sin li pali li kama tawa ijo pali lon tenpo pali wan. ona li pona kepeken ijo pini.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"nasin pali Agile pi pona mute: kulupu lili li pali lon tenpo pali lili tawa wile wan. ona li jo e pali jan, toki lili."},{"id":"scrumteam","g":"agile","word":"kulupu Scrum","text":"kulupu lili pi pali Scrum: jan lawa pi ijo, Scrum Master, jan pali ilo.","also":["Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"toki pi Scrum","text":"toki kulupu pi Scrum: lawa pi tenpo pali, toki lili suno, lukin pi tenpo pali, lukin monsi. jan mute li toki e ona \"ceremonies\".","also":["Scrum events","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"lawa pi tenpo pali","text":"toki kulupu lon open pi tenpo pali. kulupu li toki sama e tan pi tenpo pali, lipu seme li kama, nasin open.","also":["sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"wile pi tenpo pali","text":"toki wan: tenpo pali li tan seme. pali lili li ken ante, taso wile li pini la ona li pona.","also":["sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"lipu pi tenpo pali","text":"lipu ni la kulupu li wile pali e ona lon tenpo pali ni. nasin pali kulupu li lon kin.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"lipu pi ijo pali","text":"linja pi ijo ale ken kama tawa ijo pali. suli mute li lon sewi. sina kama sona la ona li ante.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"wile pi ijo pali","text":"pini suli pi ijo pali. ona li pona e ni: kulupu li ken wile e pali kama.","also":["product goal","product goals"]},{"id":"refinement","g":"agile","word":"pona e lipu","text":"tenpo mute la o lukin e lipu pi pali kama: o pona e ona, o kipisi, o nasin, o pana e sona. ni la lipu li pona tawa kama. ona li kin \"backlog grooming\".","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"lukin pi tenpo pali","text":"toki kulupu lon pini pi tenpo pali. kulupu li pana e pali pini, li kute e toki jan, tawa sona e ijo kama.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"pana pali","text":"o pana e pali pini pi pali lon tawa jan pi wile ona, lon tenpo ni.","also":["demo","demos","lukin pali"],"noTip":1},{"id":"timebox","g":"agile","word":"poki tenpo","text":"tenpo pi mute pona tawa ijo wan. tenpo li pini la sina pini, ijo ale li pini ala la kin.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"wawa pali","text":"mute pali kulupu li pini lon tenpo pali wan. kulupu li kepeken ni tawa lawa pali kama. ni li nanpa pi wawa jan ala.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"ken pali","text":"mute pali kulupu li ken jo lon tenpo, tan tenpo lape en pali ante.","noTip":1},{"id":"burndown","g":"agile","word":"sitelen pi pali awen","text":"sitelen pi pali awen lon tenpo pali, li anpa lon suno ale. linja li tawa anpa ala la ijo li awen li tawa ala.","also":["burndown chart","burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"sitelen pi pali pini","text":"sitelen pi pali pini li sewi lon tenpo. ona li poka e ale pi lawa. ni la sina lukin e tenpo kama.","also":["burnup chart","burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"lipu pali Kanban","text":"ona li lipu pali: kulupu lipu wan li tawa nasin wan pi pali, lipu li tawa insa ona.","also":["Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"nasin pi tawa kama","text":"nasin pali: pali sin li open taso lon tenpo ni: jan li jo e tenpo tawa ona. ona li pana ala e pali tawa jan pi pali mute.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"tawa pali","text":"pali li tawa pona lon lipu pali. tawa pona la lipu li tawa, li kama mute ala.","also":["flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"tenpo wile","text":"tenpo suli tan wile jan tawa pini ijo.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"tenpo pi lipu wan","text":"tenpo suli pi lipu wan: tan open pali lon tawa pini.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"mute pini","text":"mute lipu pini lon tenpo esun wan anu tenpo ante.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"nena pi pali","text":"ma wan lon pali: pali li kama mute lon ni, li awen e ale lon monsi. ona li sama anpa lawa lili pi poki telo.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"linja pi lipu sama","text":"linja lon lipu pali. ona li poki e lipu pi kulupu wan, sama pali wawa anu lipu pi kulupu wan.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"nasin pali: ona li weka e ijo ike (ijo pi pona ala tawa jan esun), li awen e tawa pali."},{"id":"waste","g":"agile","word":"ijo ike","text":"lon Lean la ijo li kepeken wawa, taso li pona ala tawa jan esun. sama ni: awen, pali sin, pali pi ijo jan ala kepeken.","noTip":1},{"id":"kaizen","g":"agile","word":"pona kama","text":"o kama pona lili lili lon tenpo ale. o ante lili, o lukin e pona. lukin monsi li nasin wan. ona li kin \"kaizen\".","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"kulupu pi lawa sama","text":"kulupu li lawa e pali ona, jan ante li toki ala e nasin.","also":["self-organising team","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"kulupu sona ale","text":"kulupu li jo e sona ale tawa pini pali: sitelen pona, pali ilo, lukin.","also":["cross-functional team","cross-functional"]},{"id":"spike","g":"agile","word":"alasa lili","text":"alasa sona lili lon tenpo lili. ona li pana e sona tawa wile sona wan, lon tenpo pi open ala pi pali lon.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"pali sin","text":"pali sin tan pali pini li pona ala.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile suli (SAFe)","text":"nasin pi kepeken Agile lon kulupu mute lon lawa suli. SAFe (Scaled Agile Framework) li nasin wan pi sona mute.","also":["scaled Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"tomo lipu ilo","text":"poki pi sitelen ilo en tenpo ante ale. ona li ken lon ilo sina, lon GitHub, anu tu.","also":["tomo lipu ilo"]},{"id":"branch","g":"build","word":"ante nasin","text":"nasin pali ante lon sitelen ilo: ante li ken lon ante ala pi nasin suli.","also":["ante nasin"]},{"id":"commit","g":"build","word":"awen sitelen","text":"sitelen awen pi sitelen ilo en toki lili pi ante. sina ken kama sin tawa ona.","also":["awen sitelen"]},{"id":"push","g":"build","word":"pana","text":"pana e sitelen awen (commit) tan ilo ni tawa sama lon linluwi, sama GitHub, tawa awen pona en kepeken jan ante."},{"id":"merge","g":"build","word":"o wan","text":"wan e ante pi nasin wan tawa nasin ante, tawa nasin suli."},{"id":"pr","g":"build","word":"wile kama","text":"wile e lukin pona en wan pi ante nasin tawa nasin suli. lipu linluwi ante li kepeken nimi \"merge request\".","also":["PR","PRs","merge request","wile kama"]},{"id":"refactor","g":"build","word":"o pona e ilo","text":"pona e sitelen ilo lon ante ala pali ona: lipu lili, nimi pona, toki sama lili."},{"id":"bug","g":"build","word":"ike ilo","text":"ijo li pali ala sama wile.","also":["ike ilo"]},{"id":"peerreview","g":"build","word":"lukin pi jan pona","text":"oko tu sin: jan ante (jan pali ala) li lukin e pali lon open pi tawa sina. ni la ike lili taso li ken tawa. lon AI-gile la AI ante li lukin e lipu ale.","also":["peer review","code review"]},{"id":"code","g":"build","word":"sitelen ilo","text":"toki pi lipu ilo: ona li toki tawa ilo e pali. ona li kin \"source code\".","also":["code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"toki ilo","text":"toki tawa sitelen ilo, sama JavaScript, Python anu Java. toki ante li pona tawa pali ante.","also":["programming language","programming languages"]},{"id":"developer","g":"build","word":"jan pali ilo","text":"jan li sitelen li ante e sitelen ilo. ona li kin \"programmer\" anu \"software engineer\".","also":["developer","developers","programmer","programmers","software engineer","dev"]},{"id":"software","g":"build","word":"ilo pi sijelo ala","text":"ilo lon ilo suli en ilo lili tawa, taso ilo ni li ilo sijelo ala (hardware).","noTip":1},{"id":"app","g":"build","word":"ilo lipu","text":"nimi lili tan application: ilo jan li kepeken tawa pali, lon ilo toki, ilo suli, anu lipu linluwi.","also":["app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"ilo linluwi","text":"ilo lon lipu linluwi. ni la sina wile ala pana e ona lon ilo sina.","also":["web app","web apps","web application"]},{"id":"frontend","g":"build","word":"selo ilo","text":"ilo pi lukin en luka: lipu, poki luka, toki. ona li lon lipu linluwi mute.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"insa ilo","text":"ilo lon monsi: ona li awen e sona, li pali tan luka sina. sama ni: ona li lukin e nimi len.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"selo en insa","text":"pali lon selo ilo en insa ilo.","also":["full stack","full-stack"]},{"id":"ui","g":"build","word":"lukin pi ilo (UI)","text":"ijo jan li lukin li kepeken lon lipu ilo: nasin, poki luka, kulupu, toki.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"pilin pi kepeken (UX)","text":"pilin tan kepeken ijo: pona, pona tawa sona, musi. anu nasa, li kepeken tenpo mute.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"ken tawa ale (a11y)","text":"o pali e ijo tawa jan ale, jan lukin ala, jan pi luka ala, jan pi ilo kute lipu.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"ilo ante suli","text":"o pali e lipu tawa suli ale pi lipu ilo, tan ilo lili tawa ilo suli.","also":["responsive design"]},{"id":"designsys","g":"build","word":"kulupu pi nasin lukin","text":"poki pi kule, nasin sitelen, poki luka, lawa. ni la lipu ale li lukin sama li pali sama.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"sijelo ilo","text":"sijelo suli pi ilo: kipisi suli li seme, ona li toki tawa ante kepeken nasin seme."},{"id":"database","g":"build","word":"poki sona (DB)","text":"poki pi sona pona. ona li sama lipu nanpa wawa. ilo li ken lukin li ken ante e ona.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"nasin pi poki sona","text":"nasin pi poki sona: lipu sona seme li lon, ijo seme li lon insa ona.","also":["database schema","schema"]},{"id":"sql","g":"build","word":"SQL","text":"nimi lili tan structured query language: toki ni li wile e sona tan poki sona mute anu ante e ona.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"sona","text":"sona ilo li awen e ona, sama nimi, esun, anu nasin.","also":["data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"ilo pana","text":"ilo suli li open tenpo ale li kute e wile pi ilo ante, sama pana e lipu linluwi tenpo sina tawa ona.","also":["server","servers"]},{"id":"client","g":"build","word":"ilo wile","text":"ilo li wile e ijo, ilo linluwi anu ilo lipu sina, li toki tawa ilo pana. lon esun la ona li jan esun kin.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"nimi lili tan application programming interface: lipu wile pi ilo wan tawa ilo ante. sama ni: sina wile e toki pi kon tan ilo pi toki kon.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"ma pi wile","text":"ijo wan lon lipu pi API: nimi lipu pi ilo ken kepeken tawa kama anu pana e ijo.","also":["endpoint","endpoints"]},{"id":"integration","g":"build","word":"wan ilo","text":"o wan e ilo tu tawa pali sama. sama ni: esun sina li pana e wile tawa ilo mani sina.","also":["integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"toki ilo wan li pana tawa ilo ante tan ona sama lon tenpo ijo li lon, sama \"mani li kama\".","also":["webhook","webhooks"]},{"id":"library","g":"build","word":"poki sitelen ilo","text":"sitelen ilo jan ante li pali. sina ken kepeken e ona, sina sitelen e ona ala.","also":["library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"sijelo open","text":"sijelo pi pali ilo. ona li lawa e mute pi nasin sitelen ilo, sama sijelo tomo sina pana e ijo insa.","also":["framework","frameworks"]},{"id":"sdk","g":"build","word":"poki ilo (SDK)","text":"poki pi ilo, sitelen ilo, sitelen lili tawa pali ilo tawa ilo suli wan.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"ilo pi wile ilo","text":"poki sitelen ilo anu ilo sitelen sina li wile e ona. o awen sin e ona. ni li suli tawa awen.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"poki ilo","text":"poki pi sitelen ilo pini. sina ken pana e ona li kepeken e ona lon pali.","also":["package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"jan lawa poki ilo","text":"ilo li kama jo e poki li sin e ona. sitelen ilo sina li wile e ona. npm li ilo pi sona mute.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"ilo pi kepeken mute tawa awen e tenpo pi ante sitelen ilo, kepeken commit en ante nasin."},{"id":"github","g":"build","word":"GitHub","text":"lipu linluwi li awen e tomo lipu Git lon linluwi. ni la kulupu li ken pana e sitelen ilo, li lukin e ante, li lukin e pali."},{"id":"vcs","g":"build","word":"awen pi ante","text":"awen e tenpo ale pi ante ale pi lipu. ni la sina sona e jan seme li ante e seme, sina ken tawa monsi. Git li pali e ni.","also":["version control","source control","version control system"]},{"id":"clone","g":"build","word":"kama sama","text":"o pali e sama ale pi tomo lipu, en tenpo ona, lon ilo sina.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"kama jo","text":"o kama jo e commit sin tan sama lon linluwi (sama GitHub) tawa ilo sina. ona li ante pi push.","also":["pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"nasin suli","text":"sitelen ilo pi nasin lawa. jan ale li pali tan ona. ona li main anu master.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"ante tu li utala","text":"ante tu li luka e linja sama lon nasin ante. ni la ilo li ken wan e ona ala. jan li anu.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"ante lukin","text":"lukin li pana e ijo ante lon tenpo tu: linja sin li lon, linja weka.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"sama pi sina","text":"tomo lipu sama sina pi jan ante. sina ken ante e ona, tomo jan ante li ante ala.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"lipu ilo lili","text":"ilo lili li pali e pali wan tan ona sama, sama pona e lipu anu open e ilo.","also":["script","scripts"],"noTip":1},{"id":"build","g":"build","word":"pali pi ilo pini","text":"o ante e sitelen ilo tawa ijo pi ken tawa. anu ijo pini ni.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"o ante tawa ilo","text":"o ante e sitelen pi jan tawa nasin pi ilo ken pali.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"nasin toki (CLI)","text":"selo pi sitelen: sina toki tawa ilo kepeken sitelen, luka ala. ona li kin \"terminal\".","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"nasin ilo (config)","text":"nasin li lawa e ilo, li awen lon poka pi sitelen ilo. ni la ante li pona.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"nasin pi tenpo open","text":"nasin li pana tawa ilo lon tenpo open. ona li pana e nimi lipu anu nimi len. ni la sitelen ilo li jo ala e ona.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"alasa e ike ilo","text":"o alasa e tan pi pakala, o pona e ona.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"pali tu","text":"jan tu (anu jan en AI) li pali lon sitelen ilo sama. jan wan li sitelen, jan wan li lukin.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"lipu sona","text":"toki sitelen pi nasin ilo anu nasin kepeken.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"lipu nanpa wan lon tomo lipu: pali li seme, nasin open li seme.","also":["README","READMEs"]},{"id":"legacy","g":"build","word":"ilo pini","text":"ilo tenpo pini li awen kepeken. ante li ike, tan jan lili li sona e ona.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"nanpa ike pi ilo","text":"nasin lili li pona tawa tenpo ni, taso ona li pali e ni: ante kama li ike li kepeken tenpo mute. ona li sama mani pi pana sin: tenpo li tawa la ona li kama suli. sina pona sin e sitelen ilo la ona li kama lili.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"lukin","text":"lukin e ni: ona li pali sama wile anu seme? ilo li lukin e ante sitelen ilo ale tan ona sama. lukin ante li ni: sina lukin e lipu pini, sina toki pona e ona lon monsi.","also":["lukin"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"nimi lili tan quality assurance: ale pi lukin e pali li pona anu seme lon open pi tawa jan. lon AI-gile la ni li lukin tan ilo: QA li loje la ijo li pakala. jan li pona e ni la taso ona li ken tawa jan.","also":["lukin pona","quality assurance"]},{"id":"testpile","g":"test","word":"lipu pi lukin sina","text":"lipu pi pali pini li awen e lukin sina, wan en wan. o pona e wan anu o pana sin e ona kepeken toki lili. ni la lipu kama li lon.","also":["test pile"]},{"id":"autotest","g":"test","word":"lukin tan ilo","text":"ilo li lukin tan ona sama lon tenpo ale pi ante sitelen ilo. ni la ike li kama sona lon open.","also":["automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"lukin tan luka","text":"jan li kepeken e pali, li lukin e ona: ona li pali sama wile anu seme.","also":["manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"lukin pi kipisi lili","text":"ilo li lukin e sitelen ilo lili wan taso.","also":["unit test","unit tests"]},{"id":"integtest","g":"test","word":"lukin pi wan ilo","text":"lukin e ni: kipisi mute li pali pona lon poka ante. ona li pali wan taso ala.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"lukin tan open tawa pini (E2E)","text":"lukin li pali sama jan kepeken lon, tan open tawa pini: kama, esun, pana mani.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"lukin tan jan wile (UAT)","text":"jan pi wile pali li kepeken e ona li toki e ni: ona li pali e wile? poki pi lukin lon AI-gile li nasin ona.","also":["UAT","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"pona li kama ike","text":"ijo pona pi tenpo pini li pakala tan ante. lukin ni li lukin e ni: ijo pini li pona kin.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"lukin wawa","text":"lukin lili wawa: ijo suli li pali anu ala? sama lon tenpo ante li tawa jan. ona li pakala la o pini, o lukin.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"lukin tawa","text":"o kepeken e ijo pali tawa nasin mute, o alasa e ike. lukin pi nasin sitelen li lukin ala e ike ni.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"lipu lukin","text":"nasin lukin wan: nasin pali, en ijo sina wile lon.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"mute lukin","text":"mute sitelen ilo ilo li lukin e ona. mute li pona tawa awen, taso mute taso li toki ala e pona.","also":["test coverage","code coverage"]},{"id":"testdata","g":"test","word":"sona lukin","text":"sona pi toki sitelen li kepeken lon lukin. ni la sona len pi jan lon li lon ala.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"ijo lon poka","text":"tenpo nasa lon poka, sama lipu pi ala anu nimi pi sitelen lili. ijo li pakala mute lon ni.","also":["edge case","edge cases"]},{"id":"happypath","g":"test","word":"nasin pona","text":"nasin ale li pona. lukin pona li alasa e nasin ike kin."},{"id":"perftest","g":"test","word":"lukin pi wawa","text":"o lukin e wawa ilo: ona li tawa wawa seme, ona li awen lon wawa seme.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"lukin pi jan mute","text":"o lukin e ni: ilo li pona kepeken jan mute lon tenpo wan.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"lukin pi awen","text":"o alasa e ma ike. jan ike li ken kepeken ona anu lukin e ijo len.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"lukin pi ken tawa ale","text":"o lukin e ni: jan pi ken ante li ken kepeken ijo pali, kepeken ilo kute anu ilo luka taso.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"lukin pi sitelen ike","text":"ilo lukin li lukin e ike en nasin ike lon sitelen ilo. ona li sama ilo pi lukin nimi.","also":["linting","linter","lint"]},{"id":"static","g":"test","word":"lukin pi sitelen","text":"ilo li lukin e sitelen ilo li alasa e ike, li open ala e ona.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"lukin pi sona ala","text":"lukin li pona lon tenpo, li ike lon tenpo ante, tan ala sona. ni la sina ken pilin e ona ala.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"o pali sin e ike","text":"o pali sin e ike kepeken nasin sama. ni la sina ken lukin e ona li pona e ona. sitelen pi nasin ni li pona mute lon lipu ike.","also":["reproduce","repro","steps to reproduce"]},{"id":"severity","g":"test","word":"suli ike","text":"ike li suli seme, tan ike lili tawa pini pi ijo ale.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"o pana tawa jan","text":"kama sama e ilo sin tawa ilo kepeken, sama kama sama lukin anu pali tawa jan."},{"id":"release","g":"change","word":"pana","text":"kulupu pi pali pini li jo e nimi, li tawa jan lon tenpo sama. lipu lili li toki e ante. 🚀 pana li sitelen e lipu ni tan lipu pali pini.","also":["release","pana sin"]},{"id":"rollback","g":"change","word":"o weka e ante","text":"tawa monsi tawa ilo pona pini tenpo ilo sin li ike. lon AI-gile la \"Roll back\" li pali e lipu pi nasin weka pi ante ale.","also":["rollback","roll back"]},{"id":"live","g":"change","word":"lon jan","text":"ilo lon. jan li kepeken e ona. ona li sama ala ilo lukin pi pali musi. jan pi pali ilo li kepeken kin e nimi production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"ante","text":"ante pi sona open lon ijo. jan mute li wile e ijo ni. sina sitelen e ni lon open: ante seme, tan seme, ike ken, tenpo seme, nasin weka seme. o open kepeken 🔀 o pana e ante.","also":["change","wile ante"],"noTip":1},{"id":"risk","g":"change","word":"ike ken","text":"ijo ike li ken kama. nanpa li toki e ni: ona li ken mute anu lili, li ike mute anu lili. ⚠️ ike ken li awen e ona ale lon lipu wan. nanpa suli li lon sewi. ijo ale li jo e tenpo pi lukin sin.","also":["risk","risks"]},{"id":"chgwin","g":"change","word":"supa tenpo pi ante","text":"tenpo ni la ante li ken tawa jan. sama open pi tenpo pimeja lon tenpo suno pi kalama ala. tenpo ante la lipu ante li ken ala pini. taso ijo li wile wawa la ona li ken.","also":["change window"]},{"id":"gonogo","g":"change","word":"o tawa / o awen","text":"lukin pini lon open pi tawa jan: jan ale pi wile ken li toki e ni: \"o tawa\" anu \"o awen\". jan ale li toki \"o tawa\" la taso ante li tawa.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"wile pona","text":"o awen e toki pona lon open pali. jan pona li pana e lipu, anu ante li kama la ona li awen lon ✅ wile pona. sina toki pona anu toki ala la ona li tawa.","also":["approval","approvals"]},{"id":"quiettime","g":"change","word":"tenpo toki ala","text":"tenpo la ijo ala li tawa jan, sama tenpo pi pana sitelen tawa jan, tenpo pi lukin pali, tenpo pimeja. kulupu li awen pali li awen lukin, taso tawa jan li awen. ona li pini la tawa li ken. ma ante la jan li kepeken nimi \"change freeze\".","also":["quiet time","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"nasin pali: jan pali ilo en jan lawa ilo li pali sama kulupu wan, kepeken ilo mute, ni la ante li tawa jan lon tenpo mute li pona."},{"id":"cicd","g":"change","word":"CI/CD","text":"ante pi jan ale li wan e ona tawa nasin suli lon tenpo mute, ilo li lukin e ona. ni la ilo li pona tawa jan lon luka wan.","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"tawa jan tan ona sama","text":"ni li tawa lili sin lon poka CD: ante ale pi lukin pona li tawa jan tan ona sama, luka ala.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"linja pali","text":"linja pi pali ilo: ante li tawa jan lon ni. sama build, lukin, pana tawa jan.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"ma ilo","text":"ilo sama wan pi pali wan: wan tawa pali, wan tawa lukin, wan tawa jan lon.","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"ma ilo pi jan pali","text":"ilo sama pi jan pali. ona li lon ilo ona. ilo li pakala la jan ala li ike.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"ma lukin","text":"ilo sama ante tawa lukin taso, ni la ilo pi jan lon li pakala ala.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"ma pini","text":"ilo sama pini li sama ilo jan lon. ni li tawa lukin pini lon open pi tawa jan.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"ijo tan build","text":"lipu anu poki li kama tan build. ona li ken awen, ken lukin, ken tawa jan.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"pona wawa","text":"pona wawa li tawa jan lon tenpo lili, lon poka pi nasin pali, tan ijo suli li pakala.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"pona lili","text":"ante lili li pona e ike anu pini e ma ike. pana pi pona awen lon tenpo lili li suli.","also":["patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"nanpa nasin","text":"nimi sama 2.4.1 li toki e nasin seme. nanpa wan li ante tan ante suli, nanpa pini li ante tan pona lili.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"lipu pi ante sin","text":"lipu lili: ni li ante lon nasin sin, tawa jan kepeken. ona li jo e pona en ike sona. ona li kin \"changelog\".","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"len ken","text":"ilo open anu pini tawa ken ilo. pali sin li tawa jan li len. ona li ken open anu pini sin, nasin sin ala.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"tawa kama","text":"o pona e nasin ike kepeken nasin sin pona lon tenpo lili, o tawa monsi ala.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"tawa jan lili","text":"ante li tawa kulupu jan lili open. ona li pona la ale li jo. nimi ni li tan waso kon: jan pi anpa ma li tawa e ona tawa sona pi ike.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"ilo tu","text":"ilo jan lon tu li lon. jan ale li tawa ilo sin lon tenpo wan. ni la ona li ike la sina ken tawa monsi.","also":["blue-green deployment","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"tawa jan pi pini ala","text":"nasin sin li tawa jan, ilo li pini ala tawa jan kepeken.","also":["zero-downtime deployment","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"pona pi ante","text":"o pona e ante: o lukin e ike, o jo e ken pona, o anu e tenpo pona. ona li kin \"change management\".","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"kulupu pi ken ante","text":"kulupu li lukin e ante suli li toki e ni: ante li ken tawa, tenpo seme.","also":["change advisory board","CAB"]},{"id":"stdchange","g":"change","word":"ante sama","text":"ante pi ike lili li pali lon nasin pona sama. ni la ken li lon open.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"ante lawa","text":"ante li wile e lukin e ken lon open pi pali.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"ante wawa","text":"ante li wile pali lon tenpo ni tawa pona e ike suli anu weka e ona. ken li kama lon tenpo lili.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"pali tan ona sama","text":"ilo li pali e pali mute tan ona sama. ni la ona li kama lon tenpo lili li sama.","also":["automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"ilo anpa","text":"ilo, linja sona, pali: ilo pi sijelo ala li tawa lon ona.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"ilo anpa lon sitelen (IaC)","text":"sitelen e ilo pana en nasin lon lipu. lipu li awen poka sitelen ilo. ni la ilo li ken kama sin sama.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"kon sewi","text":"esun e ilo, poki, pali tan kulupu suli lon linluwi, sina jo e ilo ala.","also":["cloud","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"kulupu pi kon sewi","text":"kulupu esun li esun e ilo lon linluwi. sama Amazon Web Services (AWS), Microsoft Azure anu Google Cloud.","also":["cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"tomo ilo","text":"ma lon ni ilo lipu anu lipu linluwi sina li lon li pali. jan li ken kama tawa ona. jan li esun e ma ni tan kulupu.","also":["hosting"]},{"id":"domain","g":"change","word":"nimi lipu","text":"nimi lipu jan li sitelen, sama example.com. sina esun e ona tawa sike wan, ni la o sin e ona.","also":["domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"nimi lili tan domain name system: lipu nimi pi linluwi. ona li ante e nimi sama example.com tawa ma pi ilo pona.","also":["domain name system"]},{"id":"container","g":"change","word":"poki pi ilo ale","text":"poki pini li jo e ilo en ijo ale ona li wile. ni la ona li pali sama lon ilo ale. Docker li ilo pi sona mute.","also":["container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"ilo pi sitelen (VM)","text":"ilo sitelen li lon insa pi ilo lon. ni la ilo suli wan li ken sama ilo mute.","also":["virtual machine","virtual machines","VM","VMs"]},{"id":"serverless","g":"change","word":"ilo pana ala","text":"o open e sitelen ilo, o lawa e ilo pana ala: kulupu pana li open e ona lon tenpo wile, sina pana mani tawa ijo sina kepeken."},{"id":"lb","g":"change","word":"ilo pi kipisi jan","text":"ilo li pana e jan kama tawa ilo pana mute. ni la ilo wan li kama suli mute ala.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"poki lon poka","text":"poki pi pona pi ijo sin lon poka. ni la ona li kama sin ala anu pali sin ala. sina weka e ona la lipu pi tenpo pini li ken pona.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"linja pi ilo pana (CDN)","text":"ilo pana mute lon ma ale li jo e lipu en sitelen sina lon poka jan. ni la ona li kama wawa.","also":["content delivery network","CDN"]},{"id":"migration","g":"change","word":"tawa ma","text":"o tawa e sona anu ilo tan nasin pini tawa nasin sin, anu o ante pona e nasin pi poki sona.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"pali tawa jan","text":"sina pali e ijo. jan li wile e ona. sama lipu linluwi anu ilo. sina awen e pali ona. o pana e sitelen lon “pali ni li pali tawa jan”, o toki e ni: ona li pana e seme, jan seme li kepeken, jan seme li awen lukin.","also":["service","services"]},{"id":"uptimepct","g":"run","word":"tenpo lon","text":"tenpo pali li lon mute seme, lon nanpa %. 99.9% la ona li ken pini lon tenpo lili pi nanpa 43 (minute) lon mun wan.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"lukin pi pali lon","text":"tenpo lili ale la ilo li lukin: pali sina li awen toki anu seme? ona li pakala lon tenpo mute la AI-gile li open e lipu pi pakala suli.","also":["uptime","uptime checks","uptime check"]},{"id":"statuspage","g":"run","word":"lipu pi pona pali","text":"lipu tawa jan ale. ona li toki e ni: pali li pona anu seme (laso, jelo loje, loje), li toki e sin. jan kepeken li ken lukin. ona li wile ala toki wile.","also":["status page"]},{"id":"desk","g":"run","word":"supa pi pali tawa jan","text":"ma ni la wile sona en toki pakala tan jan kepeken li kama. AI-gile li kipisi e ona ale: wile, anu pakala suli, anu sona sin. ona li sama ijo pi toki pini la AI-gile li toki e ni.","also":["supa","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"wile tawa pali","text":"jan li wile e ijo lili. sama ni: nimi jan sin anu pona lili. ona li toki ala e pakala. ona li awen tawa tenpo ona. pakala suli li tawa nanpa wan.","also":["wile","service request","service requests"]},{"id":"incident","g":"run","word":"pakala suli","text":"ijo li pakala lon tenpo ni tawa jan kepeken. sama lipu linluwi li moli anu li tawa lili. lipu 🔥 pakala suli li tawa sewi: nanpa wan la o pona sin e ona.","also":["incident","incidents"]},{"id":"major","g":"run","word":"pakala suli mute","text":"pakala suli mute: jan mute li pilin ike, anu mani anu sona li lon ike. nena wan li pana e kulupu ale tawa ona (kulupu ale), li kama e jan pi awen lukin, li wile e toki sin lon tenpo minute 30 ale.","also":["major incident"]},{"id":"oncall","g":"run","word":"awen lukin","text":"sina jan pi toki sin lon tenpo pakala, lon tenpo pimeja kin. pali tawa jan ale li jo e jan kulupu pi awen lukin. pakala suli li kama la ona li kama lon nanpa wan.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"tenpo pi toki","text":"lipu li ken awen e toki nanpa wan lon tenpo seme. sama tenpo suli wan tawa pakala suli. tenpo li pini la lipu li jo e ilo tenpo loje. ijo ala li weka lon kalama ala. nimi ante li response target.","also":["reply-by time","response target"]},{"id":"postmortem","g":"run","word":"sona pakala pini","text":"pakala suli li pini la o lukin lili e tenpo pini: seme li kama, seme li pona, seme li wile ante. o pana ala e ike tawa jan. ni li lon ala la pakala suli li ken ala pini.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"pakala","text":"tan len pi pakala suli wan anu mute. lipu 🧩 pakala li kulupu e pakala suli pi kama sin. ni la jan li alasa e tan, li pona e ona lon tenpo ale.","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"tan open","text":"tan lon pi pakala. ona li sama ala ijo ike pi lukin sina taso. o pona e tan open la pakala suli li kama ala sin.","also":["root cause"]},{"id":"workaround","g":"run","word":"nasin lili lon tenpo pakala","text":"nasin la ijo li awen pali. nasin pona lon li kama ala la o kepeken e ni. sama ni: ijo li awen tawa ala la o open sin e ona. ni li lon lipu pakala. jan ala li wile alasa sin.","also":["workaround"]},{"id":"knownerror","g":"run","word":"ike pi sona","text":"pakala la jan li sona e tan, li jo e nasin lili lon tenpo pakala, taso jan li pona ala e ona. 🧩 ike pi sona li toki e ona ale. jan ale li kepeken e nasin lili. ona li alasa ala sin.","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"lipu pali","text":"lipu pi nasin pali. ona li toki e pali wan, e pali tu, e pali ale tawa pakala pi sona. ni la tenpo ale la pali li sama li tenpo lili. pakala suli mute li pini la kulupu li ken pana e lipu sin tawa wile pona sina.","also":["runbook","runbooks"]},{"id":"ci","g":"run","word":"ijo pi ilo","text":"ijo wan la pali tawa jan sina li wile e ona. sama ni: ilo suli, nimi lipu linja, lipu lawa, ijo open, jan pana. 🗂️ ijo pi ilo li toki e ona ale tawa pali tawa jan wan wan. ni la sina sona e ni: pakala suli li ike e seme, seme li wile sin anu awen sin.","also":["ijo ilo","configuration item","configuration items"]},{"id":"expiry","g":"run","word":"tenpo pini","text":"tenpo la ijo li pini pali, sama lipu lawa pi lipu linluwi anu nimi lipu li pini. AI-gile li lukin e tenpo. tenpo suno 30 li awen la ona li pali e lipu wan tawa sin. ni la ijo ala li pini pali lon tenpo pi sona ala.","also":["tenpo pini ale","expiry","expiry date"]},{"id":"backup","g":"run","word":"awen sin","text":"sitelen sama pi sona sina tan tenpo pini. ijo li weka anu pakala la sina ken kepeken e ona. AI-gile li pali e awen sin pi supa sina lon tenpo suno ale.","also":["backup","backups"]},{"id":"restore","g":"run","word":"o kama sin","text":"o pana sin e sona tan awen sin. sina sona e ni: awen sin li ken kama sin. ni la ona li pona lon. tenpo ante la o lukin e ni.","also":["restore"]},{"id":"svcreview","g":"run","word":"lukin pi pali tawa jan","text":"lukin monsi tawa tenpo mun wan pi pali tawa jan: pakala suli open en pakala suli pona, tenpo seme la jan li kama jo e toki, tenpo pali lon, ijo nanpa kepeken. lukin pi tenpo mun li pana e ni tawa pali tawa jan ale.","also":["lukin pi tenpo mun","service review","monthly review"]},{"id":"accessreview","g":"run","word":"lukin pi ken kama","text":"tenpo suno 90 la o lukin: jan seme li ken kama insa? linja pana, nasin pi jan pona, ijo len awen. sina awen anu weka e ijo wan wan. ni la ken kama pi tenpo pini li awen ala.","also":["access review"]},{"id":"improvements","g":"run","word":"lipu pi pona sin","text":"kulupu li wile pona e ijo seme? ona ale li lon ma wan: wile tan lukin monsi, pali tan lukin, pona tan pakala. ijo wan wan li jo e nasin ona. o lukin lon 📈 pona sin.","also":["pona sin","improvements","improvement list"]},{"id":"tokencap","g":"run","word":"pini pi ijo nanpa","text":"tenpo mun la ilo pali pi pali tawa jan li ken kepeken e ijo nanpa mute ni taso. lon 80% la sina kama sona. lon 100% la pali ona pi monsi li awen tawa tenpo mun kama, anu tawa ni: sina suli e pini.","also":["token cap","token caps"]},{"id":"svcmgmt","g":"run","word":"lawa pi pali jan","text":"ale pi awen e pali li pona tawa jan: tenpo ale, suno ale.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"lipu sona pi lawa pali pona. ona li jo e pakala suli, pakala, ante. nimi li tan IT Infrastructure Library lon tenpo pini."},{"id":"itsm","g":"run","word":"lawa pi pali IT (ITSM)","text":"o lawa e ilo sama pali tawa jan, kepeken nasin pona pi wile, pakala suli, ante, pona.","also":["IT service management","ITSM"]},{"id":"managed","g":"run","word":"pali pi jan ante","text":"pali li lon, jan ante li lawa li awen e ona tawa sina, kepeken toki pi pona pali.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"jan lawa pi pali jan","text":"jan li toki e pali ale: ona li pona seme, ona li esun mute seme, ona li kama pona kepeken nasin seme.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"toki pi pona pali (SLA)","text":"toki lipu tawa jan esun: pali li pona seme. sama \"ona li lon 99.9% tenpo\" anu \"jan li toki sin lon insa pi tenpo wan\". toki ni li pakala la mani li kama sin tawa jan esun.","also":["service level agreement","SLA","SLAs"]},{"id":"slo","g":"run","word":"wile pi pona pali (SLO)","text":"wile pi kulupu tawa pona pali lon tenpo. jan li pali e ona tawa ni: ona li wawa lili mute tawa SLA. ni li pona tawa awen.","also":["service level objective","SLO","SLOs"]},{"id":"sli","g":"run","word":"nanpa pi pona pali (SLI)","text":"nanpa lon: sina lukin e ona tawa wile. sama ni: jan mute li kama pona.","also":["service level indicator","SLI","SLIs"]},{"id":"availability","g":"run","word":"ken kepeken","text":"jan li ken kepeken pali lon tenpo wile. jan li nanpa e ni kepeken tenpo lon (uptime).","also":["availability","high availability"]},{"id":"downtime","g":"run","word":"tenpo pi pali ala","text":"tenpo pali li pali ala anu pini. ni li lawa anu ala.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"mute pi ken ike","text":"mute lili pi pakala ken: wile awen sina li ken e ona. ona li awen lon la sina ken ante e ijo kepeken ike lili. ona li pini la o tawa lili.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"tenpo pakala","text":"tenpo pali li pini anu pakala mute tawa jan.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"pali ike","text":"ona li pali, taso ike: ona li tawa lili, anu kipisi li pali ala.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"lukin tenpo ale","text":"ilo li lukin e pali lon tenpo ale. ni la sina sona e ike. pona mute la jan kepeken li sona ala e ike lon tenpo ni.","also":["monitoring"]},{"id":"observability","g":"run","word":"ken lukin","text":"sina ken sona e insa ilo tan poka. kepeken lipu, nanpa, nasin.","also":["observability","o11y"]},{"id":"log","g":"run","word":"lipu tenpo","text":"lipu tenpo pi ilo: ona li pali e seme. sina kepeken ona tawa sona e tan pakala.","also":["log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"nasin tawa","text":"lipu pi wile wan li tawa nasin seme lon ilo: sina lukin e ma awen.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"tenpo awen","text":"tenpo ijo li wile tawa toki sin. sama tenpo awen tan luka tawa lipu.","also":["latency"]},{"id":"alert","g":"run","word":"toki wawa","text":"toki tan ilo: ijo li wile lukin, sama lipu linluwi li toki ala.","also":["alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"toki wawa mute","text":"toki wawa li mute la jan li kute ala e ona. toki suli kin.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"lipu pi nanpa suli","text":"lipu li pana e nanpa suli en pilin lon lukin wan.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"kalama tawa jan","text":"o kalama wawa tawa jan pi awen lukin tan ike, anu o pini e lape ona.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"tawa jan suli","text":"o kama jo e jan pi sona mute anu lawa mute. ike li ken ala pona lon ma ni, anu ona li pona lon tenpo lili ala.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"anu e ike","text":"o anu lon tenpo lili e ike kama. ike wawa en suli li kama nanpa wan.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"ante suli","text":"ijo li ante e jan: jan mute seme, ike seme.","noTip":1},{"id":"urgency","g":"run","word":"wawa tenpo","text":"ijo li wile pali lon tenpo lili seme. ante suli en wawa tenpo li lawa e nanpa.","noTip":1},{"id":"plevels","g":"run","word":"nanpa wawa (P1, P2…)","text":"nimi wawa pi ike. P1 li suli mute, li wile pali lon tenpo ni.","also":["priority levels","P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"linja lipu","text":"linja pi wile en pakala suli. ona li awen tawa jan.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"jan nanpa wan, jan nanpa tu","text":"sijelo pi pana: nanpa wan li kute li pona e ijo lili, nanpa tu li jo e sona mute tawa ike. ona li kin \"tier 1\" en \"tier 2\".","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"jan lawa pi pakala suli","text":"jan wan li lawa e pali tawa pakala suli. ni la jan ale li sona e jan seme li wile, jan seme li pali.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"tenpo pi toki open","text":"tenpo suli tan open tawa ni: jan li kama jo e wile anu pakala suli.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"tenpo pi pona","text":"tenpo suli tawa pona pini e wile anu pakala suli, tan toki tawa pona.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"tenpo pona (MTTR)","text":"tenpo pona: ona li pakala la tenpo suli seme tawa pali sin. MTTR li ken toki sama ala, ni la o toki e ijo sina nanpa.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"tenpo pi pakala ala (MTBF)","text":"tenpo pona: ilo li pali lon tenpo suli seme, ijo li pakala ala.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"lipu pi ijo ale (CMDB)","text":"lipu pi ijo ale en wan ona. ni la sina lukin e ijo li wile e seme.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"ijo mani","text":"ijo suli sina jo anu pana mani tawa pali, sama ilo nanpa, ken ilo, nimi lipu.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"lawa pi ken pali","text":"o pali e ni: wawa ilo, poki, jan li mute tawa ijo kama.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"o suli","text":"o ken pali tawa jan mute kepeken wawa ilo wan (scaling up) anu ilo mute (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"pali awen","text":"lawa tawa awen e ijo suli lon tenpo ike suli: weka tomo pali, jan pana suli, ilo.","also":["business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"kama sin tan ike suli (DR)","text":"lawa en ilo tawa kama sin pali tan ike suli, sama tomo ilo ale li weka.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"tenpo pi kama sin (RTO)","text":"tenpo pi suli nanpa wan: pali li ken pini lon tenpo ni taso, monsi ike suli. ni li pini la pali li wile lon sin.","also":["recovery time objective","RTO"]},{"id":"rpo","g":"run","word":"sona ken weka (RPO)","text":"mute pi sona sin sina ken weka, kepeken tenpo. RPO pi tenpo wan la o pali e awen sin lon tenpo wan ale.","also":["recovery point objective","RPO"]},{"id":"redundancy","g":"run","word":"ilo ante awen","text":"ilo ante li lon, sama ilo pana tu. ni la pakala wan li pini e pali ala.","also":["redundancy"]},{"id":"failover","g":"run","word":"tawa ilo ante","text":"ilo ante li kama tan ona sama tenpo ilo pi nasin sama li pakala.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"ijo wan pi pakala suli","text":"ijo wan li weka e ale tenpo ona li pakala, tan ilo ante li lon ala.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"tenpo pi pona ilo","text":"tenpo lawa: pali li ken awen anu kama lili tan pona ilo. jan kepeken li sona lon open.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"pana pali tawa jan ante","text":"o pana e pali, sona, lawa tawa jan ante anu kulupu ante. ni la ijo ala li weka.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"poki sona","text":"poki pi lipu pona en toki: tawa jan kepeken en kulupu.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"pona pi jan esun (CSAT)","text":"nanpa tan jan kepeken: ona li pilin pona seme. wile li pini la jan li toki e ni.","also":["customer satisfaction","CSAT"]},{"id":"supplier","g":"run","word":"jan pana","text":"kulupu ante sina kepeken, sama kulupu pi ma ilo. ona li kin \"vendor\" anu \"third party\".","also":["supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"pini pi pali","text":"o pini e pali lon tenpo ale, lon nasin awen: o toki tawa jan kepeken, o lawa e sona, o weka e esun.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"tenpo pini pi ilo (EOL)","text":"ilo li kama jo ala e ante anu pana tan jan pali. ni la o ante e ona.","also":["end of life","EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"awen ilo","text":"o awen e ilo en sona tan jan ike: ona li ken ala kama insa, li ken ala kama jo, li ken ala pakala e ona.","also":["cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"sona e jan","text":"o lukin e ni: jan li seme? nimi len anu nimi lili li pana e ni. ona li kin \"authn\".","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"ken jan","text":"sina sona e jan la o lukin e ni: ona li ken pali e seme? ona li kin \"authz\".","also":["authorisation","authorization","authz"]},{"id":"mfa","g":"sec","word":"kama kepeken ijo tu (MFA)","text":"kama kepeken pana tu anu mute, sama nimi len en nimi lili lon ilo toki sina. ona li kin \"2FA\".","also":["multi-factor authentication","MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"kama wan (SSO)","text":"sina kama tenpo wan, ni la sina ken tawa insa pi ilo mute. sama sina kepeken nimi pali sina lon ale.","also":["single sign-on","SSO"]},{"id":"pwmgr","g":"sec","word":"jan awen pi nimi len","text":"ilo li pali e nimi len wawa li awen e ona tawa sina.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"ijo len","text":"nimi len, ijo len anu nimi lili len. ilo li kepeken ona tawa kama insa. o pana ala e ona tawa jan, o sitelen ala e ona lon sitelen ilo.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"ijo len API","text":"nimi len li ken e ilo tawa API pi ilo ante. ona li toki e jan kepeken (en pana mani).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"lipu tenpo ken","text":"lipu ken lili: ona li toki e ni, ilo li ken kama. ni la sina pana ala e nimi len tenpo ale. ona li sama ijo nanpa pi AI ala.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"ante len","text":"o ante e sona tawa nasa: jan jo e ijo len pona taso li ken lukin.","also":["encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"nasin awen pi tawa lipu linluwi. ilo lukin li sitelen e poki len. ni la jan lon insa li ken lukin ala, ante ala."},{"id":"cert","g":"sec","word":"lipu sona len (SSL/TLS)","text":"lipu sona sama ilo: lipu linluwi li ken toki e nimi ona li kepeken e HTTPS. ona li pini la o sin e ona.","also":["SSL/TLS certificate","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"ken","text":"lawa tawa jan: jan seme li ken lukin anu ante e seme.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"ken lili","text":"o pana e ken wile taso tawa jan anu ilo wan wan, lon tenpo wile taso.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"ken tan pali (RBAC)","text":"o pana e ken tan pali, sama lukin anu ante, tan jan wan wan ala.","also":["role-based access control","RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"ma ike","text":"ma ike li ken tawa jan ike: ona li kama insa anu pali ike.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"ike pi tenpo ala","text":"ma ike jan ike li sona e ona, taso jan pali li jo ala e tenpo pi pona.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"ilo ike","text":"ilo ike, sama kasi ike, li pali tawa pakala, lukin len, anu jo ike.","also":["malware"]},{"id":"ransomware","g":"sec","word":"ilo ike pi esun","text":"ilo ike li pini e lipu sina, li wile e mani tawa open. awen sin pona li nasin awen pi pona nanpa wan.","also":["ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"toki ike pi lon ala","text":"toki lon ala li wile e ni: sina pana e nimi len anu mani anu open e ijo ike.","also":["phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"ike tawa jan","text":"o toki lon ala tawa jan, tawa ilo ala, tawa kama jo e ken. sama kalama lon ala tan \"jan pi pona ilo\"."},{"id":"firewall","g":"sec","word":"tomo len","text":"jan awen li lawa e ni: sona seme li ken kama anu weka lon linja.","also":["firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"nimi lili tan virtual private network: linja len lon linluwi. ona li tawa ilo pali lon nasin awen.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"ike pi jan mute lon (DoS, DDoS)","text":"ilo li jo e toki lon ala mute. ni la jan lon li ken kepeken ala e ona. DDoS la ona li tan ilo mute lon tenpo wan.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"lukin ike (pen test)","text":"sina pana e mani tawa jan sona pona, ona li alasa kama insa. ni la ma ike li kama sona lon tenpo pi sona ala pi jan ike.","also":["pen test","pen testing","penetration test","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"lukin pona pi awen","text":"lukin pona e awen: ona li awen pona seme tawa lipu nasin pona.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"pilin pi ike kama","text":"o pilin e ni: jan seme li ken ike tawa ijo, kepeken nasin seme. sina pali e seme tawa pini ona.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"sona li weka","text":"sona len li tawa jan ike li kama weka anu ante tan ken ala.","also":["data breach","data breaches"]},{"id":"pii","g":"sec","word":"sona jan","text":"sona ale tawa jan. jan ante li ken sona e jan ni tan sona ni: nimi, nimi lipu toki, anu ma. ona li kin \"PII\".","also":["personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"lawa pi ma Elopa tawa sona jan (ma Inli li jo e lawa ona kin): o jo e sona wile taso, o awen pona e ona, o ken tawa jan lukin anu weka e ona.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"awen sona jan","text":"awen pona e sona jan, kepeken lawa.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"lipu pi sona len","text":"lipu lon tawa jan ale: sona jan seme sina jo, tan seme, sina pali e seme.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"ken tan jan","text":"jan li toki \"pona\" lon nasin pona tawa kepeken sona ona. ona li ken weka e ni lon tenpo ale.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"lipu lili","text":"lipu lili. lipu linluwi li awen e ona lon ilo linluwi sina tawa sona, sama ni: sina kama insa. lipu lili mute li wile e ken sina lon open.","also":["cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"sona lili","text":"o jo o awen e sona jan wile taso tawa pali.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"awen sona","text":"tenpo suli pi awen sona, tawa ona weka. awen lili la ni li pona li lawa kin.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"weka e nimi jan","text":"o ante e sona. ni la jan ala li ken sona e jan tan ona.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"nimi ante","text":"o ante e nimi en sona ante tawa sitelen nanpa, nimi len li awen lon ma ante tawa wan ona. ona li awen sona jan.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"lipu pi pali sona (DPA)","text":"lipu toki: jan pana li ken pali e sona jan tawa sina kepeken nasin seme.","also":["data processing agreement","DPA"]},{"id":"dpia","g":"sec","word":"lukin pi ante sona (DPIA)","text":"lukin pona lon open: pali pi sona jan li ken ante e jan kepeken nasin seme, ike li lili kepeken nasin seme.","also":["data protection impact assessment","DPIA"]},{"id":"auditlog","g":"sec","word":"lipu pi pali ale","text":"lipu: jan seme li pali e seme lon tenpo seme. ni la tenpo kama sina ken lukin e ona.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"kepeken lawa","text":"o kepeken e lawa, nasin, nasin pona sina jo. sina ken pana e ni tawa jan.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"nasin pona lon ma ale tawa lawa pi awen sona. kulupu li ken jo e lipu sona pi nasin ni.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"lipu tan ma Mewika. jan lukin pi poka li lukin e ona, li toki e ni: kulupu li awen pona e sona pi jan esun.","also":["SOC2"]},{"id":"agent","g":"ai","word":"ilo pali","text":"AI li pali e pali tan ona sama: ona li lukin e sitelen ilo, li ante, li lukin pona, li toki sin. jan li lukin e pali ona kin.","also":["ilo pali"]},{"id":"token","g":"ai","word":"ijo nanpa","text":"sitelen lili AI li lukin li sitelen. ijo nanpa wan li suli lili tawa nimi wan. kepeken AI li nanpa kepeken ona, ni la ijo nanpa lili li awen e mute pi nasin sina.","also":["ijo nanpa"]},{"id":"hook","g":"ai","word":"ilo noka","text":"wile ilo lili pi pali sama ilo lon tenpo anu, sama open tenpo pali, tawa sona kulupu e toki sina.","also":["ilo noka"]},{"id":"ai","g":"ai","word":"AI","text":"ilo li pali e ijo jan taso li ken pali, sama sitelen, toki pi wile sona, lukin e sitelen.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"ilo kama sona (ML)","text":"nasin pi ilo kama sona: ilo li kama sona e nasin tan ijo mute, lawa pi ijo pona ala.","also":["machine learning","ML"]},{"id":"model","g":"ai","word":"ilo sona","text":"\"lawa\" pi AI. ona li kama sona tan ijo mute. ilo sona ante li sona ante, li wawa ante, li esun ante.","also":["model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"ilo pi toki suli (LLM)","text":"ilo AI li kama sona tan toki mute. ni la ona li ken lukin li ken sitelen e toki.","also":["large language model","LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI pi pali sin","text":"AI li pali e ijo sin, sama toki, sitelen, sitelen ilo. ona li kipisi taso ala, li lukin taso ala.","also":["generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"ilo toki","text":"ilo sina toki tawa ona kepeken toki jan, sitelen anu kalama.","also":["chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"toki tawa AI","text":"ijo sina pana tawa AI: wile sona anu nasin pali, en ijo ante sina pana. toki pona la AI li toki pona.","also":["prompt","prompts"]},{"id":"prompteng","g":"ai","word":"pali pi toki tawa AI","text":"sona pi sitelen toki tawa AI: ni la AI li pana e ijo pona lon tenpo ale.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"toki open pi AI","text":"toki lon monsi. AI li jo e ona lon open pi toki: ona li pana e pali en lawa. ona li suli mute tawa toki sina.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"sona lon","text":"ale AI li ken lukin tenpo pali: toki lawa, toki sina, lipu ona li lukin, toki pini.","noTip":1},{"id":"ctxwin","g":"ai","word":"poki sona AI","text":"mute sona AI li ken awen lon pilin ona tenpo wan, ona li kepeken ijo nanpa. ni li pini la sona pini li weka anu lili.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"tenpo toki","text":"toki pali wan tawa AI, tan open tawa pini. tenpo toki sin la pilin ona li sin.","also":["session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"pilin awen","text":"toki lili AI li awen lon tenpo toki mute. ni la ona li sona e wile sina en wile pini.","noTip":1},{"id":"hallucination","g":"ai","word":"AI li toki ike","text":"AI li toki e ijo li pilin wawa, taso ijo li lon ala anu ike. o lukin e sona suli.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"pana sona tawa ilo","text":"o pana e ijo mute tawa ilo sona tawa kama sona, lon open pi kepeken.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"sona pi kama sona","text":"ijo ilo li kama sona tan ona. sona ona li pini lon tenpo pi sona ni.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"tenpo pini pi sona","text":"tenpo pini pi sona lon insa AI. ona li alasa ala la ona li sona ala e ijo pi tenpo kama.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"pona e AI","text":"kama sona sin pi ilo sona tan ijo sina, tawa pona e pali wan.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"kepeken AI","text":"ilo sona li kepeken lon tenpo ni tawa toki, lon kama sona ala.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"AI li kepeken ilo","text":"AI li ken pali, toki taso ala: o open e toki, lukin e lipu, alasa lon linluwi, kepeken ilo tan ilo lipu.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"AI lili","text":"AI pi pali lili. AI suli li pana e pali lili tawa ona, li kama jo e pini.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"AI mute","text":"AI mute li pali sama lon pali wan. ona wan wan li jo e kipisi ona, sama kulupu lili.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"pali tan ona","text":"AI li ken pali mute seme tan ona sama, tenpo ni li pini la ona li wile toki tawa jan.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"jan lon insa","text":"jan li awen lon pali tawa lukin anu ken lon tenpo suli AI. lon AI-gile la jan ni li sina.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"poki awen","text":"lawa en lukin li awen pona e pali AI, sama ni: ijo li tawa jan la ken li wile lon open. ona li lili e ike, taso li weka ala e ona.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"AI li alasa e lipu (RAG)","text":"AI li alasa lon lipu sina open pi toki ona. ni la toki ona li tan sona sina.","also":["retrieval-augmented generation","RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"nanpa pi sona","text":"sitelen li kama linja nanpa, ona li jo e sona. ni la ilo li ken alasa e ijo pi sona sama.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"poki pi linja nanpa","text":"poki sona li pali tawa alasa e linja nanpa (embeddings), tawa alasa e ijo pi sona sama.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"nasin sama tawa wan e ilo en poki sona tawa ilo AI. ni la AI li ken kepeken ona.","also":["MCP"]},{"id":"temperature","g":"ai","word":"wawa pi toki AI","text":"nasin pi nasa toki AI. lili la toki li sama, li ken sona. suli la toki li ante mute. nasin tu ni li pona e toki lon tenpo ale ala.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"sona mute","text":"ken pali kepeken sona mute: toki, sitelen, kalama.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"lukin AI","text":"lukin lon nasin: AI li pali pona seme lon ijo pi wile sina. ni la sina sama e ilo sona anu toki.","also":["evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"nasin ike","text":"AI (anu jan) li tawa poka wan lon nasin ike, tan ona li kama sona tan ijo ni.","also":["bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI pona","text":"o kepeken AI lon nasin pona, awen, lon. jan li lawa e pini.","also":["responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"toki len tawa AI","text":"nasin ike: toki len lon lipu linluwi anu lipu li wile e ni: AI li pali e ijo jan kepeken li wile ala.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"lili pi wile","text":"lili pi mute wile sina ken pana tawa ilo lon tenpo. sina pana mute la o awen.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"lili pi kepeken","text":"mute pi pali AI nasin sina li ken e lon tenpo. ni li pini la ona li awen anu li esun mute.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"pali pi pilin","text":"pali e ilo kepeken toki tawa AI: sina toki e wile, AI li sitelen e sitelen ilo.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"mani pali","text":"mute mani li awen tawa ijo.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"pilin pi esun","text":"pilin pona sina: ijo li esun mute seme lon open.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"pona pi mani (ROI)","text":"sina kama jo e seme tawa ijo sina pana? sina kama jo e mute la ni li pona.","also":["return on investment","ROI"]},{"id":"tco","g":"money","word":"esun ale (TCO)","text":"ijo li esun mute seme lon tenpo ale ona, esun open taso ala: kepeken, pona, sin, pini.","also":["total cost of ownership","TCO"]},{"id":"capex","g":"money","word":"mani open en mani awen","text":"CapEx li mani pana lon open tawa ijo sina awen; OpEx li mani pana tenpo ale, sama mani mun.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"mani mun","text":"pana mani lon tenpo, mun wan anu sike wan, tawa awen kepeken.","also":["subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"ilo lon linluwi (SaaS)","text":"ilo sina kepeken lon linluwi li pana mani kepeken mani mun. jan pali li lawa e ona tawa sina.","also":["software as a service","SaaS"]},{"id":"payg","g":"money","word":"mani tan kepeken","text":"pana mani tan ijo sina kepeken taso, sama ilo sewi anu ijo nanpa AI.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"mani mute","text":"kepeken li mute tawa nasin sina. ni li esun mute.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"toki pi mani","text":"toki lon tenpo ni: mani anu kepeken li kama tawa nanpa sina wile. ona li toki e ike, taso ona li pini ala e esun lon tenpo ale.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"nasin ala mani","text":"nasin ala mani pi pali pi mani: ona li jo e lili. ona li pona tawa open.","also":["free tier","free plan"]},{"id":"pricing","g":"money","word":"nasin pi mani","text":"poki mute pi pali esun, wan wan li jo e mani en lili ona.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"ken sitelen","text":"lawa pi kepeken, kama sama, ante, anu pana e ijo jan ante li pali, sama ilo, nasin sitelen, anu sitelen.","also":["licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"sitelen ilo open","text":"ilo pi sitelen ilo open tawa jan ale. jan li ken lukin li kepeken li ante e ona, lon lawa pi ken ona.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"ken pi sitelen ilo open","text":"lawa lon sitelen ilo open. ken wan li pana e ale (sama MIT); ken ante li wile e ni: sina pana e ante sina kin (sama GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"ilo pi jan wan","text":"kulupu li jo e ona. jan ante li ken ala kama sama anu ante e ona. ona li ante pi sitelen ilo open.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"ken pi jan pali","text":"ken lawa pi jan pali tawa lawa e kama sama pi pali ona, sitelen ilo en toki li lon.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"ijo pi pilin","text":"pilin en pali la lawa li toki e ni: jan wan li jo e ona. sama sitelen ilo, sitelen pona, nimi, sitelen nimi.","also":["intellectual property","IP"]},{"id":"tos","g":"money","word":"lawa pi pali","text":"lawa sina toki \"pona\" tawa ona lon tenpo kepeken pali.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"lipu lawa","text":"toki lipu pi poka tu. lawa li awen e ona.","also":["contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"lipu pali (SOW)","text":"lipu li toki e pali ale: pali seme, lon tenpo seme, esun mute seme.","also":["statement of work","SOW"]},{"id":"fixedprice","g":"money","word":"esun wan","text":"esun toki sama tawa pali ale, tenpo pali li suli seme.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"esun tan tenpo","text":"pana mani tan tenpo pali lon en ijo kepeken lon, esun wan ala.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"lipu esun","text":"lipu li wile e mani tan pali pini anu ijo pana.","also":["invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"tawa weka li ike","text":"tawa weka tan jan pana li ike anu esun mute, ni la sina awen lon ona.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"esun tan jan pana","text":"nasin pi anu en esun tan jan pana.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"mani kama sin","text":"mani kama sin anu mani lili, tan jan pana li pakala e SLA ona.","also":["service credit","service credits"]}]}};
